using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Zyven.Application;
namespace IntegrationTests;

public class PixRecoveryTests
{
    private static async Task<HttpClient> Register(WebApplicationFactory<Program> a) { var c = a.CreateClient(new() { HandleCookies = false }); c.DefaultRequestHeaders.Add("X-Zyven-Client", "web"); var r = await c.PostAsJsonAsync("/api/auth/register", new { email = $"recovery-{Guid.NewGuid():N}@example.com", password = "recovery secure password", displayName = "Seller" }); r.EnsureSuccessStatusCode(); c.DefaultRequestHeaders.Authorization = new("Bearer", (await r.Content.ReadFromJsonAsync<AuthResponse>())!.AccessToken); return c; }
    private static async Task<JsonElement> J(HttpResponseMessage r, HttpStatusCode s = HttpStatusCode.OK) { var b = await r.Content.ReadAsStringAsync(); Assert.True(r.StatusCode == s, $"{r.StatusCode}: {b}"); return JsonSerializer.Deserialize<JsonElement>(b); }
    [Fact] public async Task Draft_validates_and_publishes_immutable_recovery_versions() { await using var app = new WebApplicationFactory<Program>(); using var owner = await Register(app); using var other = await Register(app); var org = (await J(await owner.PostAsJsonAsync("/api/organizations", new { name = "Recovery" }), HttpStatusCode.Created)).GetProperty("id").GetString()!; var product = (await J(await owner.PostAsJsonAsync($"/api/organizations/{org}/products", new { name = "Course", slug = $"course-{Guid.NewGuid():N}", description = "x", imageUrl = "https://example.com/x.png", status = "DRAFT" }), HttpStatusCode.Created)).GetProperty("id").GetString()!; var offer = (await J(await owner.PostAsJsonAsync($"/api/organizations/{org}/offers", new { productId = product, name = "Offer", slug = $"offer-{Guid.NewGuid():N}", headline = "x", description = "x", price = 10m, currency = "BRL", billingType = "ONE_TIME", status = "DRAFT" }), HttpStatusCode.Created)).GetProperty("id").GetString()!; var path = $"/api/organizations/{org}/offers/{offer}/pix-recovery"; var body = new { enabled = true, messages = new[] { new { delayMinutes = 15, emailText = "Olá {{buyer_name}} {{pix_code}}", telegramText = "PIX {{pix_code}}" }, new { delayMinutes = 120, emailText = "Oferta {{offer_name}}", telegramText = "Oferta {{offer_name}}" } } }; Assert.Equal(2, (await J(await owner.PutAsJsonAsync(path, body))).GetProperty("messages").GetArrayLength()); Assert.Equal(1, (await J(await owner.PostAsync(path + "/publish", null))).GetProperty("publishedVersion").GetInt32()); Assert.Equal(HttpStatusCode.NotFound, (await other.GetAsync(path)).StatusCode); Assert.Equal(HttpStatusCode.BadRequest, (await owner.PutAsJsonAsync(path, new { enabled = true, messages = new[] { new { delayMinutes = 15, emailText = "{{unknown}}", telegramText = "x" } } })).StatusCode); }
}
